#!/usr/bin/env node
// Build-time preparation, runs before tsc:
//   1. Generates src/version.ts from the "version" field of package.json.
//   2. Copies the resvg WASM binary into assets/.

import { createRequire } from "node:module";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

// First line of the generated src/version.ts.
const GENERATED_HEADER =
  "// Generated by scripts/prepare-build.mjs from package.json. Do not edit this file by hand.";

// Output paths, relative to the repository root.
const VERSION_TS_PATH = path.join("src", "version.ts");
const ASSETS_DIR = "assets";
const WASM_TARGET_PATH = path.join(ASSETS_DIR, "index_bg.wasm");

// Package (and the subpath inside it) whose WASM binary gets copied.
const WASM_PACKAGE = "@resvg/resvg-wasm";
const WASM_PACKAGE_FILE = "index_bg.wasm";

// The repository root is the parent folder of the folder holding this script.
const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const root = path.dirname(scriptDir);

async function main() {
  // Read the root package.json. Take its "version" field.
  const packageJsonPath = path.join(root, "package.json");
  let packageJson;
  try {
    packageJson = JSON.parse(await readFile(packageJsonPath, "utf8"));
  } catch (error) {
    throw new Error(`failed to read or parse ${packageJsonPath}: ${error?.message ?? error}`);
  }
  const version = packageJson?.version;
  if (typeof version !== "string") {
    throw new Error(`${packageJsonPath} has no "version" field, or its value is not a string`);
  }

  // Build the text of src/version.ts (UTF-8, no byte-order mark, each line
  // followed by "\n").
  const versionTsPath = path.join(root, VERSION_TS_PATH);
  const expectedText = `${GENERATED_HEADER}\nexport const ENGINE_VERSION = "${version}";\n`;

  // Write the file only when it is missing or its text differs.
  // Then a rebuild does not change its timestamp.
  let currentText;
  try {
    currentText = await readFile(versionTsPath, "utf8");
  } catch (error) {
    if (error?.code !== "ENOENT") {
      throw error;
    }
  }
  if (currentText !== expectedText) {
    await writeFile(versionTsPath, expectedText, "utf8");
  }

  // Resolve the resvg WASM file. Then read its bytes.
  const wasmSpecifier = `${WASM_PACKAGE}/${WASM_PACKAGE_FILE}`;
  let wasmSourcePath;
  try {
    wasmSourcePath = createRequire(path.join(root, "package.json")).resolve(wasmSpecifier);
  } catch (error) {
    throw new Error(`failed to resolve ${wasmSpecifier}: ${error?.message ?? error}`);
  }
  const wasmBytes = await readFile(wasmSourcePath);

  // Only after the read succeeds, create the assets folder. Then write the bytes.
  await mkdir(path.join(root, ASSETS_DIR), { recursive: true });
  await writeFile(path.join(root, WASM_TARGET_PATH), wasmBytes);
}

main()
  .then(() => {
    process.exitCode = 0;
  })
  .catch((error) => {
    process.stderr.write(`prepare-build: ${error?.message ?? error}\n`);
    process.exitCode = 1;
  });
